"""Generate crawlable supporting pages without changing the homepage app."""
from pathlib import Path
from html import escape as e
import json
ROOT=Path(__file__).resolve().parents[1]
D=ROOT/'dist'
BASE='https://aw9-club.com'
config=json.loads((D/'api/web_config').read_text())['data']
links=[('','Home'),('download/','Download'),('games/','Games'),('rewards/','Rewards'),('faq/','FAQ')]
nav=''.join(f'<a href="/{path}">{label}</a>' for path,label in links)
tg='https://t.me/+eiMNeAG0Z942NWQ1'
wa='https://whatsapp.com/channel/0029Vb96XEZ1XquVoVQuGo2O'
platforms=''.join(f'<article class="card"><img class="platform" src="{e(a["logo"])}" alt="{e(a["app_name"])}" width="80" height="80"><h2>{e(a["app_name"])}</h2>'+ (f'<p>Android APK download for {e(a["app_name"])}.</p><a class="button" href="{e(a["app_download"])}">Download {e(a["app_name"])} APK</a>' if a['app_download'] else f'<p>The AW9 download link is not available yet.</p><a href="{tg}">Follow launch updates on Telegram</a>')+'</article>' for a in config['app_list'])
pages={
'download':('AW9 App Downloads & Android Installation Guide','Find AW9 Group Android APK links for ET7, G8G, 8IN and 8HI, plus installation guidance and AW9 launch updates.',f'''<p>Choose your platform below. Each download button opens the APK link for the named app; AW9 launch updates are listed separately.</p><div class="grid">{platforms}</div><section><h2>Installing an Android APK</h2><ol><li>Choose the platform you want and download its APK.</li><li>Open the downloaded file on your Android device.</li><li>If Android asks for installation permission, review the source and permissions before continuing. Do not bypass a security warning.</li><li>Follow the installation prompts, then open the app.</li></ol><p>APK files are for Android. This page does not provide an iPhone installation file.</p></section><section><h2>If a download does not open</h2><p>Check your connection and available storage, then retry the link for the same platform. For help, use the <a href="/faq/">FAQ and contact links</a>.</p></section>'''),
'games':('AW9 Games: Card Games, Slots & Flight Games','Explore the game categories featured on AW9, including Aviator Pro, Dragon Tiger, 7Up 7Down, 3 Patti, slots and fishing games.','''<p>Browse the game types featured on the AW9 homepage. This guide explains the categories so you can find the relevant section in your chosen app.</p><div class="grid"><article class="card"><h2>Aviator Pro</h2><p>A flight game with a multiplier that increases during a round. The round can end at any time; players must cash out before it ends. The timing of a previous round does not guarantee the next result.</p></article><article class="card"><h2>Dragon Tiger</h2><p>A card comparison game built around the Dragon and Tiger positions. Review the game's rules for card values, ties and available choices before joining a round.</p></article><article class="card"><h2>7Up 7Down</h2><p>A dice game based on whether a total falls above or below seven, with a separate seven outcome where offered. Check the in-app rules for payouts and round details.</p></article><article class="card"><h2>3 Patti</h2><p>A three-card game featuring ranked hands. Table rules and available play modes can differ, so review the hand rankings shown by the game.</p></article><article class="card"><h2>Slots</h2><p>Slot games use themed reels and symbol combinations. Each game's paytable describes its winning combinations, bonus features and limits.</p></article><article class="card"><h2>Fishing games</h2><p>The homepage also features Fishing King. Open the game's own instructions for its controls, scoring and available features.</p></article></div><section><h2>Finding a game</h2><p>Choose an app from the <a href="/download/">download page</a>, then use its game menu. Availability and rules depend on the selected platform. Promotion conditions are covered separately in the <a href="/rewards/">rewards guide</a>.</p></section>'''),
'rewards':('AW9 Rewards Guide: Invitations, Daily Bonuses & Rebates','Understand AW9 invitation rewards, daily free spins, Daily Double Bonus and loss rebate conditions before claiming.','''<p>This guide separates the reward types shown on the homepage. Check the matching event inside your app for eligibility, deadlines and the amount available to your account.</p><section><h2>Invitation wheel</h2><p>The homepage advertises a ₹1,000 bonus per invitation and free spins that reset each day. An invitation bonus and a daily free spin are separate parts of this offer. The wheel image shows possible prize amounts, not an account balance.</p></section><section><h2>Agent invitation rewards</h2><p>The agent rules shown on this website require the invited user to register through the invitation link or code, deposit at least ₹200 and meet the ₹600 betting requirement. Those rules list ₹100 for the inviter and ₹20 for the invited user.</p><p>These agent rewards are a separate event from the invitation wheel. Check which event your invitation belongs to before expecting a reward.</p></section><section><h2>Daily Double Bonus</h2><p>Your tier is based on yesterday's total recharge. A qualifying tier has a free reward and a separate paid reward that requires a further deposit. If the previous day's recharge does not reach the minimum tier, no reward is available for that day.</p><p>For example, the published ₹100–₹299 tier lists a ₹1 free reward and a ₹7 paid reward with a ₹100 deposit requirement. The ₹300–₹999 tier lists ₹3 free and ₹20 paid with a ₹300 deposit requirement.</p></section><section><h2>Daily loss rebate</h2><p>The published table lists rebate rates from 1% to 2.8%, depending on the loss-rate level. Pending rebates become claimable after settlement. Check the event page for the calculation and your settled amount.</p></section><section><h2>Before claiming or withdrawing</h2><ul><li>Match the reward to its event; conditions are not identical across promotions.</li><li>Check the deadline and whether a claim is automatic or manual.</li><li>Review the turnover requirement. The reward-wheel rules on the homepage list 5× turnover before withdrawal.</li><li>Use the event's claim history to check previous claims.</li></ul><p>See <a href="/faq/">help and contact options</a> for an account-specific question, or return to the <a href="/">homepage</a> for the detailed reward tables.</p></section>'''),
'faq':('AW9 FAQ: Downloads, Launch Updates & Reward Help','Answers about AW9 downloads, Android APK files, invitation bonuses, daily rewards and Telegram or WhatsApp contact links.',f'''<p>Find practical answers about the website and its app links. For account-specific information, include the platform name when contacting support.</p><section><h2>Where can I download an app?</h2><p>The <a href="/download/">download page</a> lists the available ET7, G8G, 8IN and 8HI APK links. The AW9 app itself does not yet have a download link on this website.</p></section><section><h2>Can I install an APK on an iPhone?</h2><p>No. APK is an Android application format. The website currently provides Android APK links, not an iOS installation package.</p></section><section><h2>Where can I find AW9 launch updates?</h2><p>Use the <a href="{tg}">AW9 Telegram channel</a>. The homepage also displays the launch popup.</p></section><section><h2>Is the ₹1,000 invitation offer the same as the agent reward?</h2><p>No. The homepage describes them as separate events. The invitation wheel advertises ₹1,000 per invitation, while the agent invitation rules list a different reward and qualification requirements. Read the <a href="/rewards/">rewards guide</a> and the matching in-app event.</p></section><section><h2>Why is a daily bonus unavailable?</h2><p>For Daily Double Bonus, the tier uses yesterday's recharge. If that amount does not meet the minimum tier, no reward is available today. Other events have their own claim conditions.</p></section><section><h2>Where are the detailed game rules?</h2><p>The <a href="/games/">games guide</a> introduces the featured categories. The selected game's in-app rules contain its specific controls, payouts and conditions.</p></section><section><h2>How can I contact AW9?</h2><p>Use the published <a href="{tg}">Telegram</a> or <a href="{wa}">WhatsApp channel</a>. For a reward question, identify the app and event so the correct conditions can be checked.</p></section>''')}
css='''*{box-sizing:border-box}body{margin:0;background:#191e1c;color:#eef1ef;font:16px/1.7 system-ui,sans-serif}a{color:#a6f250;text-underline-offset:4px}a:hover{color:#d4ffad}a:focus-visible{outline:3px solid #a6f250;outline-offset:4px}header,main,footer{max-width:1120px;margin:auto;padding:24px}header{border-bottom:1px solid #3b453e}header>a{display:inline-flex;align-items:center;gap:12px;color:#ffe39b;font-weight:800;text-decoration:none;font-size:24px}header img{width:42px;height:42px;object-fit:contain}nav{display:flex;flex-wrap:wrap;gap:12px 24px;margin-top:18px}h1{font-size:clamp(28px,4vw,44px);line-height:1.2;max-width:850px}h2{font-size:22px;line-height:1.35}p{max-width:78ch}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,290px),1fr));gap:20px;margin:28px 0}.card,section{padding:24px;border:1px solid #3b453e;border-radius:16px;background:#222925}section{margin:20px 0}.platform{object-fit:contain;border-radius:12px}.button{display:inline-block;background:#95ed32;color:#102009;border-radius:28px;padding:10px 20px;font-weight:700;text-decoration:none}.button:hover{background:#c2ff79;color:#102009}footer{margin-top:32px;border-top:1px solid #3b453e;padding-bottom:48px}.crumb{font-size:14px;color:#b9c1bc}li+li{margin-top:10px}@media(max-width:600px){header,main,footer{padding:20px}.card,section{padding:20px}}'''
(D/'brand/support-pages.css').write_text(css)
for slug,(title,desc,body) in pages.items():
 url=f'{BASE}/{slug}/'; folder=D/slug;folder.mkdir(exist_ok=True)
 schema={'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':BASE+'/'},{'@type':'ListItem','position':2,'name':slug.title(),'item':url}]}
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><meta name="robots" content="index, follow"><link rel="canonical" href="{url}"><link rel="icon" href="/global/192.png"><meta property="og:type" content="website"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}/brand/aw9-share-1000-oct22.png"><link rel="stylesheet" href="/brand/support-pages.css"><script type="application/ld+json">{json.dumps(schema)}</script></head><body><header><a href="/"><img src="/brand/aw9-symbol.png" alt="" width="42" height="42">AW9</a><nav aria-label="Main navigation">{nav}</nav></header><main><p class="crumb"><a href="/">Home</a> / {slug.title()}</p><h1>{e(title)}</h1>{body}</main><footer><strong>Explore AW9</strong><nav aria-label="Related pages">{nav}</nav><p><a href="/">Return to the AW9 homepage</a></p></footer></body></html>'''
 (folder/'index.html').write_text(html)
(D/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>{BASE}/{path}</loc></url>\n' for path,_ in links)+'</urlset>\n')
home=D/'index.html';s=home.read_text();start='<!-- AW9 supporting pages -->';end='<!-- /AW9 supporting pages -->'
import re
s=re.sub(re.escape(start)+'.*?'+re.escape(end),'',s,flags=re.S)
footer=f'{start}<footer class="aw9-support-links"><nav aria-label="AW9 guides">{nav}</nav></footer>{end}'
s=s.replace('</body>',footer+'\n</body>');home.write_text(s)
p=D/'brand/aw9-labels.css';s=p.read_text();marker='/* Supporting page links */';s=s.split(marker)[0].rstrip();p.write_text(s+'\n'+marker+'\n.aw9-support-links{background:#191e1c;border-top:1px solid #3b453e;padding:24px 20px 40px}.aw9-support-links nav{display:flex;justify-content:center;flex-wrap:wrap;gap:16px 28px}.aw9-support-links a{color:#a6f250;font:600 15px/1.5 system-ui,sans-serif;text-decoration:underline;text-underline-offset:4px}.aw9-support-links a:focus-visible{outline:2px solid #a6f250;outline-offset:5px}\n')
print('Generated four supporting pages, homepage footer links and five-URL sitemap.')
